UPDATE algoritmos.questions SET prompt = $prompt$Calcula una calificación ponderada de tres componentes. Ingresa primero las tres notas (nota 1, nota 2 y nota 3), y luego los tres porcentajes (peso 1, peso 2 y peso 3). Los porcentajes suman 100.$prompt$, evaluation_config = $cfg${"casos":[{"entradas":["16","18","14","30","30","40"],"salida":["15.8"],"visible":true},{"entradas":["18","22","20","33","35","32"],"salida":["20.04"],"visible":true},{"entradas":["32","72","84","20","30","50"],"salida":["70"],"visible":false}],"estructura":{"requiere":["DECLARACION","LECTURA","ESCRITURA"]},"comparacion":{"modo":"numeros","tolerancia":0.000001}}$cfg$::jsonb WHERE question_id = 1355;

UPDATE algoritmos.questions SET expected_answer = NULL WHERE lower(question_type) IN ('codigo','codigo_pseudocodigo');

DO $check$ BEGIN
  IF EXISTS (
    SELECT 1 FROM algoritmos.questions
    WHERE lower(question_type) IN ('codigo','codigo_pseudocodigo')
      AND CASE
        WHEN jsonb_typeof(evaluation_config->'casos') = 'array'
          THEN jsonb_array_length(evaluation_config->'casos') = 0
        ELSE TRUE
      END
  ) THEN
    RAISE EXCEPTION 'Migración cancelada: hay preguntas de código sin casos de prueba.';
  END IF;
END $check$;

COMMIT;
